input.command:
awk -F',' '
NR==1 { next }
{
  # Check if lead_speed (field 3) is empty or not
  current_empty = ($3 == "" || $3 ~ /^[[:space:]]*$/) ? 1 : 0
  if (NR == 2) {
    prev_empty = current_empty
  }
  if (current_empty != prev_empty) {
    if (current_empty) {
      printf "TRANSITION at line %d (time=%s): lead vehicle DISAPPEARS\n", NR, $1
    } else {
      printf "TRANSITION at line %d (time=%s): lead vehicle APPEARS\n", NR, $1
    }
  }
  prev_empty = current_empty
}
' /root/sensor_data.csv
